def transform(grid):
    sep = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))
    counts = {}
    for color in (2, 4):
        counts[color] = sum(row.count(color) for row in grid[sep + 1:])
    color = 4 if counts[4] > counts[2] and counts[4] - counts[2] > 1 else 2
    return [[color, color], [color, color]]
